import math
def dot(a,b): return sum(x*y for x,y in zip(a,b))
def cos(a,b):
    na = math.sqrt(dot(a,a)); nb = math.sqrt(dot(b,b))
    return dot(a,b)/(na*nb)

text_q = [0.9, 0.1, 0.2]
img_embs = {
    "cat.png": [0.8, 0.2, 0.1],
    "dog.png": [0.1, 0.9, 0.2],
    "car.png": [0.2, 0.1, 0.9],
}
ranked = sorted(img_embs.items(), key=lambda kv: cos(text_q, kv[1]), reverse=True)
print("查询向量:", text_q)
for name, e in ranked:
    print(f"{name}: {cos(text_q,e):.3f}")
print("Top1:", ranked[0][0])
